import groovy.json.JsonSlurper
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.commons.io.IOUtils
import java.nio.charset.StandardCharsets

def ff = session.get()
if (ff == null) return

try {
    String text = ''
    session.read(ff, { inputStream ->
        text = IOUtils.toString(inputStream, StandardCharsets.UTF_8)
    } as InputStreamCallback)

    def arr = new JsonSlurper().parseText(text)
    if (!(arr instanceof List)) {
        ff = session.putAttribute(ff, "groovy.error", "Expected JSON array")
        session.transfer(ff, REL_FAILURE)
        return
    }

    long totalBytes = 0L
    boolean anyFailure = false

    arr.each { item ->
        def bw = item?.bytes_written
        long bytes = 0L
        if (bw != null && bw.toString().trim() != '') {
            bytes = bw.toString().toLong()
        }
        totalBytes += bytes

        def status = item?.activity_status?.toString()
        if (status != 'SUCCESS') {
            anyFailure = true
        }
    }

    ff = session.putAttribute(ff, "total_bytes_written", totalBytes.toString())
    ff = session.putAttribute(ff, "final_status", anyFailure ? "FAILURE" : "SUCCESS")

    session.transfer(ff, REL_SUCCESS)
    return

} catch (Exception e) {
    ff = session.putAttribute(ff, "groovy.error", (e.message ?: e.class.name))
    session.transfer(ff, REL_FAILURE)
    return
}
